#!/bin/zsh
# Darcy sweep at the Andersen inertia (χ=8, ρ*=2.52, I*=0.16), Re_g=1900, L=64, 60 c/U.
# Dimensionless Brinkman resistance is 1/(Re·Da): at Re ~ 10³ the relevant range is Da = 1e-6 … 1e-4.
# Do NOT edit this file while it runs (zsh reads scripts incrementally).
cd ~/Developer/FallingPlate2D.jl
run() { name=$1; shift; echo "=== $(date '+%H:%M') start $name" >> logs/chain_da.log
        julia -t 4 --project=. examples/free_fall.jl "$1" "$2" "$3" "$4" "$5" "$name" "${6:-0}" > logs/run_$name.log 2>&1
        echo "=== $(date '+%H:%M') end $name exit $?" >> logs/chain_da.log; }
run sweep_Re1900_Da0     8 2.52 1900 64 60 0
run sweep_Re1900_Da1e-6  8 2.52 1900 64 60 1e-6
run sweep_Re1900_Da1e-5  8 2.52 1900 64 60 1e-5
run sweep_Re1900_Da3e-5  8 2.52 1900 64 60 3e-5
run sweep_Re1900_Da1e-4  8 2.52 1900 64 60 1e-4
echo "=== $(date '+%H:%M') DA SWEEP DONE" >> logs/chain_da.log
